// ANALYSIS ONLY - not part of the app. Runs the UNCHANGED src/lib/planner.js
// on real candidate geometry (scripts/scenario/candidates.json, generated by
// gen_candidates.py from the raw sources) and prints kept/dropped decisions.
import fs from 'node:fs';
import { buildPlan } from '../../src/lib/planner.js';

const legsData = JSON.parse(fs.readFileSync(new URL('../../public/data/legs.json', import.meta.url)));
const cand = JSON.parse(fs.readFileSync(new URL('./candidates.json', import.meta.url)));
legsData.legs = { ...legsData.legs, ...cand.legs };
const base = [{ id: 'Wildcat' }, { id: 'Skinner' }];
const DWELL = 60, PACE = 1.0; // declared assumptions (UI defaults)

function show(label, cfg) {
  const p = buildPlan({ dwellMin: DWELL, paceKmh: PACE, legsData, ...cfg });
  const route = p.visitedLegs.map(l => l.to).concat(p.sim.legs.map(l => l.to)).join(' -> ');
  console.log(`  ${label}`);
  console.log(`    route: Base -> ${route} | total ${(p.elapsed + p.sim.total).toFixed(1)} min (elapsed ${p.elapsed.toFixed(1)}), dist ${(p.visitedLegs.reduce((a, l) => a + l.metrics.dist, 0) + p.sim.dist).toFixed(1)} m, asc ${p.sim.asc.toFixed(1)} m`);
  console.log(`    kept: [${p.kept.map(s => s.id)}] dropped: [${p.dropped.map(d => d.id + ' (' + d.reason + ')')}]${p.infeasible ? ' INFEASIBLE shortfall ' + p.shortfall.toFixed(1) : ''}`);
}

for (const c of cand.stations) {
  const stops = base.concat([{ id: c.id }]);
  console.log(`${c.id} (${c.feature}, sample sol ${c.sampleSol}, record sol ${c.recordSol}, ${c.lat},${c.lon}):`);
  show('A. window 300, prio Wildcat1 Skinner2 ' + c.id + '3, no must-haves:',
    { stops, priorities: { Wildcat: 1, Skinner: 2, [c.id]: 3 }, mustHaves: [], windowMin: 300 });
  show('B. window 240, same priorities (planner drops lowest non-must):',
    { stops, priorities: { Wildcat: 1, Skinner: 2, [c.id]: 3 }, mustHaves: [], windowMin: 240 });
  show('C. window 240, prio Wildcat1 ' + c.id + '2 Skinner3 (Skinner lowest):',
    { stops, priorities: { Wildcat: 1, [c.id]: 2, Skinner: 3 }, mustHaves: [], windowMin: 240 });
  show('D. +60 overrun at Wildcat (visited, dwellUsed 120), window 300, prio as A:',
    { stops, priorities: { Wildcat: 1, Skinner: 2, [c.id]: 3 }, mustHaves: [], windowMin: 300,
      visited: [{ id: 'Wildcat', dwellUsed: 120, walkMin: 380.19 / (PACE * 1000 / 60), paceUsed: PACE }] });
  console.log('');
}
